auto simpson_rule = [](FunctionPtr func, double a, double b) {
    double c = (a + b) / 2.0;
    return (std::abs(b - a) / 6.0) * (func(a) + 4.0 * func(c) + func(b));
};

auto recursive_step = [&](auto self, FunctionPtr func, double a, double b, double eps, double whole) -> double {
    double mid = (a + b) / 2.0;
    double left = simpson_rule(func, a, mid);
    double right = simpson_rule(func, mid, b);
    if (std::abs(left + right - whole) <= 15.0 * eps) {
        return left + right + (left + right - whole) / 15.0;
    }
    return self(self, func, a, mid, eps / 2.0, left) + self(self, func, mid, b, eps / 2.0, right);
};

return recursive_step(recursive_step, f, a, b, precision, simpson_rule(f, a, b));
